`timescale 1 ns / 10 ps

module uart_receiver(clk, wb_rst_i, lcr, rf_pop, srx_pad_i, enable, counter_t, 
	rf_count, rf_data_out, rf_error_bit, rf_overrun, rx_reset, lsr_mask, 
	rstate, rf_push_pulse);

	parameter		sr_idle		= 4'b0;
	parameter		sr_rec_start	= 4'b1;
	parameter		sr_rec_bit	= 4'd2;
	parameter		sr_rec_parity	= 4'd3;
	parameter		sr_rec_stop	= 4'd4;
	parameter		sr_check_parity	= 4'd5;
	parameter		sr_rec_prepare	= 4'd6;
	parameter		sr_end_bit	= 4'd7;
	parameter		sr_ca_lc_parity	= 4'd8;
	parameter		sr_wait1	= 4'd9;
	parameter		sr_push		= 4'd10;

	input			clk;
	input			wb_rst_i;
	input	[7:0]		lcr;
	input			rf_pop;
	input			srx_pad_i;
	input			enable;
	input			rx_reset;
	input			lsr_mask;
	output	[9:0]		counter_t;
	output	[(5 - 1):0]	rf_count;
	output	[(11 - 1):0]	rf_data_out;
	output			rf_overrun;
	output			rf_error_bit;
	output	[3:0]		rstate;
	output			rf_push_pulse;

	reg	[3:0]		rcounter16;
	reg	[2:0]		rbit_counter;
	reg	[7:0]		rshift;
	reg			rparity;
	reg			rparity_error;
	reg			rframing_error;
	reg			rbit_in;
	reg			rparity_xor;
	reg	[7:0]		counter_b;
	reg			rf_push_q;
	reg	[(11 - 1):0]	rf_data_in;
	reg			rf_push;
	wire			break_error = (counter_b == 0);
	wire			rcounter16_eq_7 = (rcounter16 == 4'd7);
	wire			rcounter16_eq_0 = (rcounter16 == 4'b0);
	wire			rcounter16_eq_1 = (rcounter16 == 4'b1);
	wire	[3:0]		rcounter16_minus_1 = (rcounter16 - 1'b1);
	reg	[9:0]		toc_value;
	wire	[7:0]		brc_value;
	reg	[9:0]		counter_t;
	reg	[3:0]		rstate;

	assign rf_push_pulse = (rf_push & (~rf_push_q));
	assign brc_value = toc_value[9:2];

	uart_rfifo #(11) fifo_rx(
		.clk				(clk), 
		.wb_rst_i			(wb_rst_i), 
		.data_in			(rf_data_in), 
		.data_out			(rf_data_out), 
		.push				(rf_push_pulse), 
		.pop				(rf_pop), 
		.overrun			(rf_overrun), 
		.count				(rf_count), 
		.error_bit			(rf_error_bit), 
		.fifo_reset			(rx_reset), 
		.reset_status			(lsr_mask));

	always @(posedge clk or posedge wb_rst_i) begin
	  if (wb_rst_i) begin
	    rstate <= #(1) sr_idle;
	    rbit_in <= #(1) 1'b0;
	    rcounter16 <= #(1) 0;
	    rbit_counter <= #(1) 0;
	    rparity_xor <= #(1) 1'b0;
	    rframing_error <= #(1) 1'b0;
	    rparity_error <= #(1) 1'b0;
	    rparity <= #(1) 1'b0;
	    rshift <= #(1) 0;
	    rf_push <= #(1) 1'b0;
	    rf_data_in <= #(1) 0;
	  end
	  else if (enable) begin
	    case (rstate)
	      sr_idle: begin
		rf_push <= #(1) 1'b0;
		rf_data_in <= #(1) 0;
		rcounter16 <= #(1) 4'b1110;
		if ((srx_pad_i == 1'b0) & (~break_error)) begin
		  rstate <= #(1) sr_rec_start;
		end
	      end
	      sr_rec_start: begin
		rf_push <= #(1) 1'b0;
		if (rcounter16_eq_7) begin
		  if (srx_pad_i == 1'b1) begin
		    rstate <= #(1) sr_idle;
		  end
		  else begin
		    rstate <= #(1) sr_rec_prepare;
		  end
		end
		rcounter16 <= #(1) rcounter16_minus_1;
	      end
	      sr_rec_prepare: begin
		case (lcr[1:0])
		  2'b0:
		    rbit_counter <= #(1) 3'd4;
		  2'b1:
		    rbit_counter <= #(1) 3'd5;
		  2'b10:
		    rbit_counter <= #(1) 3'd6;
		  2'b11:
		    rbit_counter <= #(1) 3'd7;
		endcase
		if (rcounter16_eq_0) begin
		  rstate <= #(1) sr_rec_bit;
		  rcounter16 <= #(1) 4'b1110;
		  rshift <= #(1) 0;
		end
		else begin
		  rstate <= #(1) sr_rec_prepare;
		end
		rcounter16 <= #(1) rcounter16_minus_1;
	      end
	      sr_rec_bit: begin
		if (rcounter16_eq_0) begin
		  rstate <= #(1) sr_end_bit;
		end
		if (rcounter16_eq_7) begin
		  case (lcr[1:0])
		    2'b0:
		      rshift[4:0] <= #(1) {srx_pad_i, rshift[4:1]};
		    2'b1:
		      rshift[5:0] <= #(1) {srx_pad_i, rshift[5:1]};
		    2'b10:
		      rshift[6:0] <= #(1) {srx_pad_i, rshift[6:1]};
		    2'b11:
		      rshift[7:0] <= #(1) {srx_pad_i, rshift[7:1]};
		  endcase
		end
		rcounter16 <= #(1) rcounter16_minus_1;
	      end
	      sr_end_bit: begin
		if (rbit_counter == 3'b0) begin
		  if (lcr[3]) begin
		    rstate <= #(1) sr_rec_parity;
		  end
		  else
		    begin
		      rstate <= #(1) sr_rec_stop;
		      rparity_error <= #(1) 1'b0;
		    end
		end
		else
		  begin
		    rstate <= #(1) sr_rec_bit;
		    rbit_counter <= #(1) (rbit_counter - 1'b1);
		  end
		rcounter16 <= #(1) 4'b1110;
	      end
	      sr_rec_parity: begin
		if (rcounter16_eq_7) begin
		  rparity <= #(1) srx_pad_i;
		  rstate <= #(1) sr_ca_lc_parity;
		end
		rcounter16 <= #(1) rcounter16_minus_1;
	      end
	      sr_ca_lc_parity: begin
		rcounter16 <= #(1) rcounter16_minus_1;
		rparity_xor <= #(1) (^{rshift, rparity});
		rstate <= #(1) sr_check_parity;
	      end
	      sr_check_parity: begin
		case ({lcr[4], lcr[5]})
		  2'b0:
		    rparity_error <= #(1) (rparity_xor == 0);
		  2'b1:
		    rparity_error <= #(1) (~rparity);
		  2'b10:
		    rparity_error <= #(1) (rparity_xor == 1);
		  2'b11:
		    rparity_error <= #(1) rparity;
		endcase
		rcounter16 <= #(1) rcounter16_minus_1;
		rstate <= #(1) sr_wait1;
	      end
	      sr_wait1:
		if (rcounter16_eq_0) begin
		  rstate <= #(1) sr_rec_stop;
		  rcounter16 <= #(1) 4'b1110;
		end
		else begin
		  rcounter16 <= #(1) rcounter16_minus_1;
		end
	      sr_rec_stop: begin
		if (rcounter16_eq_7) begin
		  rframing_error <= #(1) (!srx_pad_i);
		  rstate <= #(1) sr_push;
		end
		rcounter16 <= #(1) rcounter16_minus_1;
	      end
	      sr_push: begin
		if (srx_pad_i | break_error) begin
		  if (break_error) begin
		    rf_data_in <= #(1) {8'b0, 3'd4};
		  end
		  else begin
		    rf_data_in <= #(1) {rshift, 1'b0, rparity_error, 
			    rframing_error};
		  end
		  rf_push <= #(1) 1'b1;
		  rstate <= #(1) sr_idle;
		end
		else if (~rframing_error) begin
		  rf_data_in <= #(1) {rshift, 1'b0, rparity_error, 
			  rframing_error};
		  rf_push <= #(1) 1'b1;
		  rcounter16 <= #(1) 4'b1110;
		  rstate <= #(1) sr_rec_start;
		end
	      end
	      default:
		rstate <= #(1) sr_idle;
	    endcase
	  end
	end
	always @(posedge clk or posedge wb_rst_i) begin
	  if (wb_rst_i) begin
	    rf_push_q <= 0;
	  end
	  else begin
	    rf_push_q <= #(1) rf_push;
	  end
	end
	always @(lcr) case (lcr[3:0])
	  4'b0:
	    toc_value = 447;
	  4'd4:
	    toc_value = 479;
	  4'b1, 4'd8:
	    toc_value = 511;
	  4'b1100:
	    toc_value = 543;
	  4'd2, 4'd5, 4'd9:
	    toc_value = 575;
	  4'd3, 4'd6, 4'd10, 4'b1101:
	    toc_value = 639;
	  4'd7, 4'b1011, 4'b1110:
	    toc_value = 703;
	  4'b1111:
	    toc_value = 767;
	endcase
	always @(posedge clk or posedge wb_rst_i) begin
	  if (wb_rst_i) begin
	    counter_b <= #(1) 8'd159;
	  end
	  else if (srx_pad_i) begin
	    counter_b <= #(1) brc_value;
	  end
	  else if (enable & (counter_b != 8'b0)) begin
	    counter_b <= #(1) (counter_b - 1);
	  end
	end
	always @(posedge clk or posedge wb_rst_i) begin
	  if (wb_rst_i) begin
	    counter_t <= #(1) 10'd639;
	  end
	  else if ((rf_push_pulse || rf_pop) || (rf_count == 0)) begin
	    counter_t <= #(1) toc_value;
	  end
	  else if (enable && (counter_t != 10'b0)) begin
	    counter_t <= #(1) (counter_t - 1);
	  end
	end
endmodule
