`timescale 1 ns / 10 ps
module uart_tfifo(clk, wb_rst_i, data_in, data_out, push, pop, overrun, count, 
	fifo_reset, reset_status);

	parameter		fifo_width	= 8;
	parameter		fifo_depth	= 16;
	parameter		fifo_pointer_w	= 4;
	parameter		fifo_counter_w	= 5;

	input			clk;
	input			wb_rst_i;
	input			push;
	input			pop;
	input	[(fifo_width - 1):0]
				data_in;
	input			fifo_reset;
	input			reset_status;
	output	[(fifo_width - 1):0]
				data_out;
	output			overrun;
	output	[(fifo_counter_w - 1):0]
				count;

	reg	[(fifo_pointer_w - 1):0]
				top;
	reg	[(fifo_pointer_w - 1):0]
				bottom;
	reg			overrun;
	reg	[(fifo_counter_w - 1):0]
				count;
	wire	[(fifo_pointer_w - 1):0]
				top_plus_1 = (top + 1'b1);


	raminfr #(fifo_pointer_w, fifo_width, fifo_depth) tfifo(
		.clk				(clk), 
		.we				(push), 
		.a				(top), 
		.dpra				(bottom), 
		.di				(data_in), 
		.dpo				(data_out));

	always @(posedge clk or posedge wb_rst_i) begin
	  if (wb_rst_i) begin
	    top <= #(1) 0;
	    bottom <= #(1) 1'b0;
	    count <= #(1) 0;
	  end
	  else if (fifo_reset) begin
	    top <= #(1) 0;
	    bottom <= #(1) 1'b0;
	    count <= #(1) 0;
	  end
	  else
	    begin
	      case ({push, pop})
		2'b10:
		  if (count < fifo_depth) begin
		    top <= #(1) top_plus_1;
		    count <= #(1) (count + 1'b1);
		  end
		2'b1:
		  if (count > 0) begin
		    bottom <= #(1) (bottom + 1'b1);
		    count <= #(1) (count - 1'b1);
		  end
		2'b11: begin
		  bottom <= #(1) (bottom + 1'b1);
		  top <= #(1) top_plus_1;
		end
		default:
		  ;
	      endcase
	    end
	end
	always @(posedge clk or posedge wb_rst_i) begin
	  if (wb_rst_i) begin
	    overrun <= #(1) 1'b0;
	  end
	  else if (fifo_reset | reset_status) begin
	    overrun <= #(1) 1'b0;
	  end
	  else if (push & (count == fifo_depth)) begin
	    overrun <= #(1) 1'b1;
	  end
	end
endmodule
