`timescale 1 ns / 10 ps
module uart_top(wb_clk_i, wb_rst_i, wb_adr_i, wb_dat_i, wb_dat_o, wb_we_i, 
	wb_stb_i, wb_cyc_i, wb_ack_o, wb_sel_i, int_o, stx_pad_o, srx_pad_i, 
	rts_pad_o, cts_pad_i, dtr_pad_o, dsr_pad_i, ri_pad_i, dcd_pad_i, baud_o)
	;

	parameter		uart_data_width	= 8;
	parameter		uart_addr_width	= 3;

	input			wb_clk_i;
	input			wb_rst_i;
	input	[(uart_addr_width - 1):0]
				wb_adr_i;
	input	[(uart_data_width - 1):0]
				wb_dat_i;
	output	[(uart_data_width - 1):0]
				wb_dat_o;
	input			wb_we_i;
	input			wb_stb_i;
	input			wb_cyc_i;
	input	[3:0]		wb_sel_i;
	output			wb_ack_o;
	output			int_o;
	input			srx_pad_i;
	output			stx_pad_o;
	output			rts_pad_o;
	input			cts_pad_i;
	output			dtr_pad_o;
	input			dsr_pad_i;
	input			ri_pad_i;
	input			dcd_pad_i;
	output			baud_o;

	wire	[7:0]		wb_dat8_i;
	wire	[7:0]		wb_dat8_o;
	wire	[31:0]		wb_dat32_o;
	wire	[(uart_addr_width - 1):0]
				wb_adr_int;
	wire			we_o;
	wire			re_o;

	uart_wb wb_interface(
		.clk				(wb_clk_i), 
		.wb_rst_i			(wb_rst_i), 
		.wb_dat_i			(wb_dat_i), 
		.wb_dat_o			(wb_dat_o), 
		.wb_dat8_i			(wb_dat8_i), 
		.wb_dat8_o			(wb_dat8_o), 
		.wb_dat32_o			(32'b0), 
		.wb_sel_i			(4'b0), 
		.wb_we_i			(wb_we_i), 
		.wb_stb_i			(wb_stb_i), 
		.wb_cyc_i			(wb_cyc_i), 
		.wb_ack_o			(wb_ack_o), 
		.wb_adr_i			(wb_adr_i), 
		.wb_adr_int			(wb_adr_int), 
		.we_o				(we_o), 
		.re_o				(re_o));
	uart_regs regs(
		.clk				(wb_clk_i), 
		.wb_rst_i			(wb_rst_i), 
		.wb_addr_i			(wb_adr_int), 
		.wb_dat_i			(wb_dat8_i), 
		.wb_dat_o			(wb_dat8_o), 
		.wb_we_i			(we_o), 
		.wb_re_i			(re_o), 
		.modem_inputs			({cts_pad_i, dsr_pad_i,
		ri_pad_i, dcd_pad_i}), 
		.stx_pad_o			(stx_pad_o), 
		.srx_pad_i			(srx_pad_i), 
		.rts_pad_o			(rts_pad_o), 
		.dtr_pad_o			(dtr_pad_o), 
		.int_o				(int_o), 
		.baud_o				(baud_o));

	initial begin
	  $display("(%m) UART INFO: Data bus width is 8. No Debug interface.\n")
		  ;
	  $display("(%m) UART INFO: Has baudrate output\n");
	end
endmodule
