`timescale 1 ns / 10 ps
module uart_transmitter(clk, wb_rst_i, lcr, tf_push, wb_dat_i, enable, 
	stx_pad_o, tstate, tf_count, tx_reset, lsr_mask);

	parameter		s_idle		= 3'b0;
	parameter		s_send_start	= 3'b1;
	parameter		s_send_byte	= 3'd2;
	parameter		s_send_parity	= 3'd3;
	parameter		s_send_stop	= 3'd4;
	parameter		s_pop_byte	= 3'd5;

	input			clk;
	input			wb_rst_i;
	input	[7:0]		lcr;
	input			tf_push;
	input	[7:0]		wb_dat_i;
	input			enable;
	input			tx_reset;
	input			lsr_mask;
	output			stx_pad_o;
	output	[2:0]		tstate;
	output	[(5 - 1):0]	tf_count;

	reg	[4:0]		counter;
	reg	[2:0]		bit_counter;
	reg	[6:0]		shift_out;
	reg			stx_o_tmp;
	reg			parity_xor;
	reg			tf_pop;
	reg			bit_out;
	reg	[(8 - 1):0]	tf_data_in;
	wire	[(8 - 1):0]	tf_data_out;
	reg	[2:0]		tstate;
	wire			tf_overrun;

	assign stx_pad_o = (lcr[6] ? 1'b0 : stx_o_tmp);

	uart_tfifo fifo_tx(
		.clk				(clk), 
		.wb_rst_i			(wb_rst_i), 
		.data_in			(tf_data_in), 
		.data_out			(tf_data_out), 
		.push				(tf_push), 
		.pop				(tf_pop), 
		.overrun			(tf_overrun), 
		.count				(tf_count), 
		.fifo_reset			(tx_reset), 
		.reset_status			(lsr_mask));

	always @(posedge clk) tf_data_in <= wb_dat_i;
	always @(posedge clk or posedge wb_rst_i) begin
	  if (wb_rst_i) begin
	    tstate <= #(1) s_idle;
	    stx_o_tmp <= #(1) 1'b1;
	    counter <= #(1) 5'b0;
	    shift_out <= #(1) 7'b0;
	    bit_out <= #(1) 1'b0;
	    parity_xor <= #(1) 1'b0;
	    tf_pop <= #(1) 1'b0;
	    bit_counter <= #(1) 3'b0;
	  end
	  else if (enable) begin
	    case (tstate)
	      s_idle:
		if (~|tf_count) begin
		  tstate <= #(1) s_idle;
		  stx_o_tmp <= #(1) 1'b1;
		end
		else
		  begin
		    tf_pop <= #(1) 1'b0;
		    stx_o_tmp <= #(1) 1'b1;
		    tstate <= #(1) s_pop_byte;
		  end
	      s_pop_byte: begin
		tf_pop <= #(1) 1'b1;
		case (lcr[1:0])
		  2'b0: begin
		    bit_counter <= #(1) 3'd4;
		    parity_xor <= #(1) (^tf_data_out[4:0]);
		  end
		  2'b1: begin
		    bit_counter <= #(1) 3'd5;
		    parity_xor <= #(1) (^tf_data_out[5:0]);
		  end
		  2'b10: begin
		    bit_counter <= #(1) 3'd6;
		    parity_xor <= #(1) (^tf_data_out[6:0]);
		  end
		  2'b11: begin
		    bit_counter <= #(1) 3'd7;
		    parity_xor <= #(1) (^tf_data_out[7:0]);
		  end
		endcase
		{shift_out[6:0], bit_out} <= #(1) tf_data_out;
		tstate <= #(1) s_send_start;
	      end
	      s_send_start: begin
		tf_pop <= #(1) 1'b0;
		if (~|counter) begin
		  counter <= #(1) 5'b01111;
		end
		else if (counter == 5'b1) begin
		  counter <= #(1) 0;
		  tstate <= #(1) s_send_byte;
		end
		else begin
		  counter <= #(1) (counter - 1'b1);
		end
		stx_o_tmp <= #(1) 1'b0;
	      end
	      s_send_byte: begin
		if (~|counter) begin
		  counter <= #(1) 5'b01111;
		end
		else if (counter == 5'b1) begin
		  if (bit_counter > 3'b0) begin
		    bit_counter <= #(1) (bit_counter - 1'b1);
		    {shift_out[5:0], bit_out} <= #(1) {shift_out[6:1], 
			    shift_out[0]};
		    tstate <= #(1) s_send_byte;
		  end
		  else if (~lcr[3]) begin
		    tstate <= #(1) s_send_stop;
		  end
		  else
		    begin
		      case ({lcr[4], lcr[5]})
			2'b0:
			  bit_out <= #(1) (~parity_xor);
			2'b1:
			  bit_out <= #(1) 1'b1;
			2'b10:
			  bit_out <= #(1) parity_xor;
			2'b11:
			  bit_out <= #(1) 1'b0;
		      endcase
		      tstate <= #(1) s_send_parity;
		    end
		  counter <= #(1) 0;
		end
		else begin
		  counter <= #(1) (counter - 1'b1);
		end
		stx_o_tmp <= #(1) bit_out;
	      end
	      s_send_parity: begin
		if (~|counter) begin
		  counter <= #(1) 5'b01111;
		end
		else if (counter == 5'b1) begin
		  counter <= #(1) 4'b0;
		  tstate <= #(1) s_send_stop;
		end
		else begin
		  counter <= #(1) (counter - 1'b1);
		end
		stx_o_tmp <= #(1) bit_out;
	      end
	      s_send_stop: begin
		if (~|counter) begin
		  casex ({lcr[2], lcr[1:0]})
		    3'b0xx:
		      counter <= #(1) 5'b01101;
		    3'd4:
		      counter <= #(1) 5'b10101;
		    default:
		      counter <= #(1) 5'b11101;
		  endcase
		end
		else if (counter == 5'b1) begin
		  counter <= #(1) 0;
		  tstate <= #(1) s_idle;
		end
		else begin
		  counter <= #(1) (counter - 1'b1);
		end
		stx_o_tmp <= #(1) 1'b1;
	      end
	      default:
		tstate <= #(1) s_idle;
	    endcase
	  end
	  else begin
	    tf_pop <= #(1) 1'b0;
	  end
	end
endmodule
