//
// Author: Jacob Gorban   (jacob.gorban@flextronicssemi.com)
// Company: Flextronics Semiconductor
//

`timescale 1 ns / 10 ps
module uart_wb(clk, wb_rst_i, wb_we_i, wb_stb_i, wb_cyc_i, wb_ack_o, wb_adr_i, 
	wb_adr_int, wb_dat_i, wb_dat_o, wb_dat8_i, wb_dat8_o, wb_dat32_o, 
	wb_sel_i, we_o, re_o);

	input			clk;
	input			wb_rst_i;
	input			wb_we_i;
	input			wb_stb_i;
	input			wb_cyc_i;
	input	[3:0]		wb_sel_i;
	input	[(3 - 1):0]	wb_adr_i;
	input	[7:0]		wb_dat_i;
	output	[7:0]		wb_dat_o;
	output	[(3 - 1):0]	wb_adr_int;
	input	[7:0]		wb_dat8_o;
	output	[7:0]		wb_dat8_i;
	input	[31:0]		wb_dat32_o;
	output			wb_ack_o;
	output			we_o;
	output			re_o;

	reg	[7:0]		wb_dat_is;
	reg	[(3 - 1):0]	wb_adr_is;
	reg			wb_we_is;
	reg			wb_cyc_is;
	reg			wb_stb_is;
	reg	[3:0]		wb_sel_is;
	reg	[7:0]		wb_dat_o;
	reg	[7:0]		wb_dat8_i;
	reg			wb_ack_o;
	reg			wre;
	reg	[1:0]		wbstate;

	assign we_o = (wb_we_is & wb_ack_o);
	assign re_o = ((((~wb_we_is) & wb_stb_is) & wb_cyc_is) & wre);
	assign wb_adr_int = wb_adr_is;

	always @(posedge clk or posedge wb_rst_i) if (wb_rst_i) begin
	  wb_ack_o <= #(1) 1'b0;
	  wbstate <= #(1) 0;
	  wre <= #(1) 1'b1;
	end
	else begin
	  case (wbstate)
	    0: begin
	      if (wb_stb_is & wb_cyc_is) begin
		wre <= #(1) 0;
		wbstate <= #(1) 1;
		wb_ack_o <= #(1) 1;
	      end
	      else
		begin
		  wre <= #(1) 1;
		  wb_ack_o <= #(1) 0;
		end
	    end
	    1: begin
	      wb_ack_o <= #(1) 0;
	      wbstate <= #(1) 2;
	      wre <= #(1) 0;
	    end
	    2, 3: begin
	      wb_ack_o <= #(1) 0;
	      wbstate <= #(1) 0;
	      wre <= #(1) 0;
	    end
	  endcase
	end
	always @(posedge clk or posedge wb_rst_i) if (wb_rst_i) begin
	  wb_adr_is <= #(1) 0;
	  wb_we_is <= #(1) 0;
	  wb_cyc_is <= #(1) 0;
	  wb_stb_is <= #(1) 0;
	  wb_dat_is <= #(1) 0;
	  wb_sel_is <= #(1) 0;
	end
	else
	  begin
	    wb_adr_is <= #(1) wb_adr_i;
	    wb_we_is <= #(1) wb_we_i;
	    wb_cyc_is <= #(1) wb_cyc_i;
	    wb_stb_is <= #(1) wb_stb_i;
	    wb_dat_is <= #(1) wb_dat_i;
	    wb_sel_is <= #(1) wb_sel_i;
	  end
	always @(posedge clk or posedge wb_rst_i) if (wb_rst_i) begin
	  wb_dat_o <= #(1) 0;
	end
	else begin
	  wb_dat_o <= #(1) wb_dat8_o;
	end
	always @(wb_dat_is) wb_dat8_i = wb_dat_is;
endmodule
