			.sctag6_cpx_atom_cq		(sctag6_cpx_atom_cq), 
			.sctag6_cpx_data_ca		(sctag6_cpx_data_ca[145:0]), 
			.sctag6_cpx_req_cq		(sctag6_cpx_req_cq[7:0]), 
