`celldefine
module cl_sc1_l1hdr_8x(l2clk, se, pce, pce_ov, stop, l1clk);

	input			l2clk;
	input			se;
	input			pce;
	input			pce_ov;
	input			stop;
	output			l1clk;

	reg			l1en;

	assign l1clk = ((l2clk & l1en) | se);

	always @(l2clk or stop or pce or pce_ov) begin
	  if (~l2clk) begin
	    l1en <= ((~stop) & (pce | pce_ov));
	  end
	end
endmodule
`endcelldefine

`celldefine
module cl_sc1_msff_8x(q, so, d, l1clk, si, siclk, soclk);

	parameter		SIZE		= 1;

	output			q;
	output			so;
	input			d;
	input			l1clk;
	input			si;
	input			siclk;
	input			soclk;

	reg			q;
	reg			l1;

	assign so = q;

	always @(posedge l1clk or posedge siclk) begin
	  if (siclk) begin
	    q <= 1'b0;
	  end
	  else
	    begin
	      q <= d;
	    end
	end
endmodule
`endcelldefine

`celldefine
module msff_ctl_macro__width_5(din, l1clk, scan_in, siclk, soclk, dout, scan_out
	);

	input	[4:0]		din;
	input			l1clk;
	input			scan_in;
	input			siclk;
	input			soclk;
	output	[4:0]		dout;
	output			scan_out;

	wire	[4:0]		fdin;
	wire	[3:0]		so;

	assign fdin[4:0] = din[4:0];

	dff #(5) d0_0(
		.l1clk				(l1clk), 
		.siclk				(siclk), 
		.soclk				(soclk), 
		.d				(fdin[4:0]), 
		.si				({scan_in, so[3:0]}), 
		.so				({so[3:0], scan_out}), 
		.q				(dout[4:0]));
endmodule
`endcelldefine

`celldefine
module buff_macro__dbuff_32x__stack_none__width_1(din, dout);

	input	[0:0]		din;
	output	[0:0]		dout;

	buff #(1) d0_0(
		.in				(din[0]), 
		.out				(dout[0]));
endmodule
`endcelldefine

`celldefine
module buff_macro__dbuff_8x__stack_none__width_1(din, dout);

	input	[0:0]		din;
	output	[0:0]		dout;

	buff #(1) d0_0(
		.in				(din[0]), 
		.out				(dout[0]));
endmodule
`endcelldefine

