  .siclk(siclk),
  .soclk(soclk)  
 
              ) ; 
 
//assign  vuad_array_wr_en1_c3 = ((inst_vld_c3 & ~wr_disable_c3) &~mbist_run_r1) |  // normal write 
//				(bistordiag_wr_vd_c3 & mbist_run_r1); // bist or diag write 

assign  vuad_array_wr_en1_c3 = ((inst_vld_c3 & ~wr_disable_c3) &~mbist_run_r1) | // normal write
			bistordiag_wr_vd_c3;

