assign pdecode0_in[6:0] = {  pku_idest_p[0],pku_fdest_p[0],pku_fsrc_rd_p[0],pku_lsu_p[0],pku_fgu_p[0],
			  pku_pdist_p[0],pku_twocycle_p[0] & pku_lsu_p[0] };
									    
