input		ect_br_taken_z1_e;
input		ect_alignaddress_little_e;
input		ect_as_clip_e_;			// ALIGNADDRESS clipping of bit [2:0]
input		ect_as_cin_e;
input  [1:0]	ect_array_sel_e;
input  [7:0]	ect_edge_lmask_e;
input  [7:0]	ect_edge_lrmask_e;
