  );

fgu_fac_ctl_spare_ctl_macro__num_5 spares  (  // spares: 13 gates + 1 flop for each "num"
  .scan_in(spares_scanin),
  .scan_out(spares_scanout),
  .l1clk(l1clk),
  .siclk(siclk),
  .soclk(soclk)
