  ({3{(fcc_vld_fb[3]    & (fac_w1_tid_fb[2:0]     == 3'd0))}} & 3'd6) |  // FCMP(E) fcc3
  ({3{(fsr_w1_qvld_fb   & (fac_w1_tid_fb[2:0]     == 3'd0))}} & 3'd7) |  // other FPop w1
  ({3{(fsr_w2_qvld_fb   & (fac_fpd_tid_fb[2:0]    == 3'd0))}} & 3'd7) ;  // other FPop FDIV/FSQRT

