assign  fac_rs2_rotate_sel_e[0] =  // odd  FiTO(s,d)
  (fpx_itype_e[2:0] == 3'b011) & (fpx_stype_e[1:0] == 2'b10) &  r2_odd32b_e;

assign  fac_rs2_rotate_sel_e[1] =  // even FiTO(s,d)
  (fpx_itype_e[2:0] == 3'b011) & (fpx_stype_e[1:0] == 2'b10) & ~r2_odd32b_e;

assign  fac_rs2_rotate_sel_e[2] =  //      FiTO(s,d)
