fgu_fac_ctl_msff_ctl_macro__width_3 fx2_02  (
  .scan_in(fx2_02_scanin),
  .scan_out(fx2_02_scanout),
  .l1clk(l1clk_pm2),
  .din ({exu_fgu_flush_m,           // requires free running clk
         exu_fgu_gsr_vld_m[1:0]}),  // requires free running clk
  .dout({exu_flush_fx2,
         fac_gsr_w_vld_fx2[1:0]}),
