  .clk (l2clk),
  .en  (asi_clken),
  .din (fgd_rngl_cdbus_3f[31:0]),
  .dout(    rngl_cdbus_4f[31:0]),
  .se(se),
  .siclk(siclk),
  .soclk(soclk),
