  );

fgu_fad_dp_mux_macro__buffsel_none__mux_aonpe__ports_2__width_1 even_en_ld  ( 
  .din0(lsu_fgu_fld_32b_b    ),
  .din1(lsu_fgu_fld_32b_b_   ),
  .sel0(lsu_fgu_fld_odd32b_b_),
  .sel1(1'b1                 ),
