         rs1_sign_fx2,
         rs2_sign_fx2,
         fadd_logical_sub_fx2,
         logical_sub_fx2,
         fadd_logical_add_fx2,
             hi_aof_fx2,
             lo_aof_fx2,
         aux_eint_eminm1_fx2,
         aux_eint_eminm2_fx2,
         aux_enable_unf_fx2,
         rd_mode_fx2[1:0],
         ns_mode_fx2,
         fst_valid_fx2,
         gsr_imirnd_fx2[2:0],
             fgx_pdist_fx2,
         exu_src_fx2}),
