                 idiv0_trap_fb,
             fcc_fb[1:0],
             fsr_w1_result_fb[11:0],
             fsr_w2_result_fb[11:0]}),
  .dout({fgu_fpx_ieee_trap_fw,
         fgu_fpd_ieee_trap_fw,
         fgu_fpx_unfin_fw,
         fgu_fpd_unfin_fw,
         fgu_fpd_idiv0_trap_fw,
         fpc_fcc_fw[1:0],
         fpc_fsr_w1_result_fw[11:0],
         fpc_fsr_w2_result_fw[11:0]}),
  .siclk(siclk),
  .soclk(soclk)
  );


