// ----------------------------------------------------------------------------
// Interface with FAC
// ----------------------------------------------------------------------------

input    [9:0] fac_aexp_fmt_sel_e;     // aop exponent format mux select
input    [7:0] fac_bexp_fmt_sel_e;     // bop exponent format mux select
