input       lsu_gkt_pmen;

// inputs from core
input       ifu_l15_valid;
input       mmu_l15_valid;
input       lsu_l15_valid;
input       spu_l15_valid;


input       lsu_l15_lock;


input [39:0] ifu_l15_addr;
input [39:4] mmu_l15_addr;
input [39:0] lsu_l15_addr;
input [38:3] spu_l15_addr;


