 .lsu_l15_addr8_6 (lsu_l15_addr[8:6]),
 .spu_l15_addr8_6 (spu_l15_addr[8:6]),
 )
 */

gkt_ipc_ctl ipc (/*AUTOINST*/
                 // Outputs
                 .ipc_v0_ifu_new        (ipc_v0_ifu_new),
                 .ipc_v0_ifu_shft       (ipc_v0_ifu_shft),
