  tcu_scan_en, 
  l2clk, 
  scan_in, 
  tcu_pce_ov, 
  spc_aclk, 
  spc_bclk, 
  const_cpuid, 
  mct_early_req, 
  ftu_cmiss, 
  ftu_rep_way, 
  ftu_thrx_un_cacheable, 
  ifu_l15_addr, 
  csm_valid_req, 
  l15_spc_data1, 
  l15_spc_cpkt, 
  l15_ifu_valid, 
  l15_ifu_grant, 
  lsu_ifu_ld_index, 
  cmu_fill_paddr, 
  mdp_lsi_nc_bit, 
  mdp_lsi_inv_bit, 
  mdp_lsi_rway, 
  lsu_ifu_cmu_pmen, 
  lsc_fill_rtn1, 
  lsc_fill_rtn2, 
  lsc_req_sel, 
  lsc_pending_req, 
  lsc_l15_valid, 
  lsc_data_sel, 
  cmu_any_data_ready, 
  cmu_any_un_cacheable, 
  cmu_data_ready, 
  cmu_inst0_v, 
  cmu_inst1_v, 
  cmu_inst2_v, 
  cmu_inst3_v, 
  cmu_icache_invalidate, 
  cmu_icache_invalidate_way, 
  cmu_icache_invalidate_index, 
  cmu_evic_invalidate, 
  cmu_icache_inv_way1, 
  cmu_inval_ack, 
  cmu_l2_err, 
  cmu_l2miss, 
  ifu_l15_valid, 
  ifu_l15_cpkt, 
  lsc_clken, 
  ifu_lsu_if_vld, 
  ifu_lsu_if_tid, 
  ifu_lsu_if_addr, 
  scan_out) ;
