assign mct_e7_wom[7:0] = ({next_e7wom_bit7, next_e7wom_bit6, next_e7wom_bit5, next_e7wom_bit4,
                           next_e7wom_bit3, next_e7wom_bit2, next_e7wom_bit1, next_e7wom_bit0});

