assign ibq_buf1_sel_lsb   = ftu_fetch_thr_c &   ~ftu_redirect_bf & ((nxt_fp[1]    &  ftu_bus_0_is_first  & ftu_instr_valid_c[0])  | 
                                                 (nxt_fp[1] & ftu_bus_1_is_first  & ftu_instr_valid_c[1])  | 		      
				 	         (nxt_fp[1] & ftu_bus_2_is_first  & ftu_instr_valid_c[2])  |      
