input	[7:0]	tlu_lsu_pstate_priv;	// PSTATE.PRIV setting
input	[7:0]	tlu_tl_gt_0;		// Indicates TL>0
input	[7:0]	tlu_lsu_clear_ctl_reg_;	// Clear ASI_LSU_CONTROL_REG
input	[54:0]	tlu_tte;		// (Really just a copy of the fast ring)

