output		lsu_fgu_fld_odd32b_b;	// FRF load return to odd 32b dest
output		lsu_fgu_fsr_load_b;	// FP load dest is %fsr, not FRF
output		lsu_fgu_exception_w;	// Signal exceptions to FGU (for STFSR)
