module lsu_adc_ctl (
  asi_e, 
  asi_m, 
  lsu_va_m, 
  sr_inst_e, 
  pr_inst_e, 
  hpr_inst_e, 
  sr_inst_m, 
  pr_inst_m, 
  hpr_inst_m, 
  altspace_ldst_e, 
  altspace_ldst_m, 
  ld_inst_vld_m, 
  legal_asi_va_m, 
  asi_legal_e, 
  asr_legal_m, 
  asi_sync_m, 
  asi_internal_e, 
  asi_rngf_m, 
  asi_indet_m, 
  lendian_asi_m, 
  asi_sz_byte_m, 
  asi_sz_hw_m, 
  pst_asi_m, 
  asi_pst8_m, 
  asi_pst16_m, 
  asi_pst32_m, 
