  atomic_asi_m, 
  blk_asi_e, 
  nofault_asi_m, 
  asi_iomap_m, 
  asi_no_va_check_m);
wire indet_m;


input	[7:0]	asi_e;
input	[7:0]	asi_m;			// This version has SR/PR/HPR muxed in
input	[11:3]	lsu_va_m;
input		sr_inst_e;
input		pr_inst_e;
input		hpr_inst_e;
input		sr_inst_m;
input		pr_inst_m;
input		hpr_inst_m;
input		altspace_ldst_e;
input		altspace_ldst_m;
input		ld_inst_vld_m;

output		legal_asi_va_m;
output		asi_legal_e;
output		asr_legal_m;
output		asi_sync_m;
output		asi_internal_e ;
output		asi_rngf_m;
