  cic_cpq_wptr, 
  cic_cpq_rptr, 
  cic_cpq_rd_en, 
  cic_cpq_wr_en, 
  cic_d1_sel, 
  cic_cpq_sel, 
  cic_fifo_sel, 
  cic_byp_sel, 
  cic_fifo_clken, 
  cic_l2fill_vld_e, 
  cic_cpq_ld_rdy, 
