lsu_tgd_dp_cmp_macro__width_32 cmp_pa_39_16  (
	.din0	({8'b0,watchpoint_b[39:16]}),
	.din1	({8'b0,tlb_pgnum[39:16]}),
	.dout	(pa_wp_39_16)
