module lsu_tld_dp_mux_macro__mux_aope__ports_2__stack_70c__width_13 (
  din0, 
  din1, 
  sel0, 
  dout);
wire psel0;
wire psel1;

  input [12:0] din0;
  input [12:0] din1;
  input sel0;
  output [12:0] dout;





cl_dp1_penc2_8x  c0_0 (
 .sel0(sel0),
 .psel0(psel0),
