mmu_asi_ctl_msff_ctl_macro__width_2 hwtw_config_4_lat  ( // FS:wmr_protect
	.scan_in(hwtw_config_4_lat_wmr_scanin),
	.scan_out(hwtw_config_4_lat_wmr_scanout),
	.siclk(spc_aclk_wmr),
