	.din0	(ecc_mux_0		[7:0]	),
	.din1	(ecc_mux_1		[7:0]	),
	.din2	(ecc_mux_2		[7:0]	),
	.dout	(ecc_out		[7:0]	)
);



supply0 vss; // <- port for ground
supply1 vdd; // <- port for power

endmodule



