 .scan_out(pred4_lat_scanout),
 .l1clk( l1clk),
 .din  ({pred_idx4_in[5:0], pred_bit4_in[1:0]}),
 .dout ({pred_idx4[5:0], pred_bit4[1:0]}),
  .siclk(siclk),
