);

mmu_seg_dp_prty_macro__width_8 check7_0_pty  (
	.din	(check7_bus	[7:0]	),
	.dout	(check7_0		)
);

mmu_seg_dp_prty_macro__width_8 check7_pty  (
	.din	({check7_bus	[35:32],
		  check7_3	       ,
		  check7_2	       ,
		  check7_1	       ,
		  check7_0	       }),
	.dout	(c7			)
);

assign ecc_out[7:0] = 
       {c7, c6, c5, c4, c3, c2, c1, c0};




supply0 vss; // <- port for ground
supply1 vdd; // <- port for power

endmodule



