wire spares_scanout;


input           l2clk;
input           scan_in;
input           tcu_pce_ov;               // scan signals
input		spc_aclk;
input		spc_bclk;
input		tcu_scan_en;

input [7:0]     htc_data_rcvd_hw1;
input [7:0]     htc_tlb_miss_m;
