  l1clk, 
  scan_in, 
  spc_aclk, 
  spc_bclk, 
  data_rcvd_hw1, 
  tlb_miss_m, 
  tsb_done_hw2, 
  vld_tsbptr_m2, 
  thr_valid_m1, 
  thr_valid_m0, 
  cindex_bit0, 
  cindex_bit1, 
  hwtw_burst, 
  trs_eperr_st, 
  trs_eccerr_st, 
  tsm_tsb_miss_hw2, 
  tsm_rqv, 
  tsm_waitfortte, 
  scan_out);
wire siclk;
wire soclk;
wire [1:0] cindex;
wire goto_null_state;
wire null_state;
wire validreq_state;
wire seqm1_state;
wire seqm2_state;
