    assign exp_stb_ld_partial_raw = (ctest02 | ctest03);


   spc_mb0_ctlmsff_ctl_macro__width_3 stb_hit_cmp_delay  (
                 .scan_in(stb_hit_cmp_delay_scanin),
                 .scan_out(stb_hit_cmp_delay_scanout),
