	.dout	({msf0_cmp_tick_enable		       ,
		  msf0_core_running[7:0]	       ,
                  msf0_wmr_vec_mask                    }),
  .clk(clk),
  .siclk(siclk),
  .soclk(soclk),
  .pce_ov(pce_ov),
  .stop(stop)
);

spc_msf0_dpbuff_macro__dbuff_32x__rep_1__stack_none__width_5 bank4_rep1  (
	.din    ({tcu_atpg_mode,
