// Maintain decr
assign decr_reg_in[63:46] =
	({18 {~wr_decr_2}} & decr_reg	[63:46]) |
	({18 { wr_decr_2}} & data_1	[63:46]) ;

tlu_asi_ctl_msff_ctl_macro__width_18 decr_lat  (
