assign tct_b_in_b =
       ~(((dec_br_taken_m & ~exu_cecc_m & ~exu_uecc_m) | 
	 dec_done_inst_m | dec_retry_inst_m) & 
        dec_inst_valid_m & ~dec_illegal_inst_m & pstate_tct_m);

