assign perf_trap_w_in = 
       (| (perf_trap_b[3:0] & ~trl_tlz_exc[3:0])) &
       ~dsc_req_in & 
       ~por_req_in & ~xir_req_in & ~ftt_req_in & 
       ~sir_b;

