assign check_mqr_dqr[3:0] =
       ~check_mqr_dqr_[3:0];
assign check_rqr_[3:0] =
       ~(asi_check_qr_exc[3:0] & {4 {trl_check_rqr}});
assign check_rqr[3:0] =
       ~check_rqr_[3:0];

assign pmqr_exc_in[3:0] = 
       ({4 {~tsd_mrqr_exc_ & ~tsa_tca_ecc_error}} & check_mqr_dqr [3:0]) |
