// Save CWP on flush

assign cwp3_in[2:0] =
        ({3 { flush_ifu[3]}} & exu_cwp3[2:0]) | 
	({3 {~flush_ifu[3]}} & cwp3[2:0]);
assign cwp2_in[2:0] =
        ({3 { flush_ifu[2]}} & exu_cwp2[2:0]) | 
	({3 {~flush_ifu[2]}} & cwp2[2:0]);
assign cwp1_in[2:0] =
        ({3 { flush_ifu[1]}} & exu_cwp1[2:0]) | 
	({3 {~flush_ifu[1]}} & cwp1[2:0]);
assign cwp0_in[2:0] =
        ({3 { flush_ifu[0]}} & exu_cwp0[2:0]) | 
	({3 {~flush_ifu[0]}} & cwp0[2:0]);

