	.din0	(fls_npc_if_cnt_eq_1_d	[4:2]	),
	.din1	({3 {inst_cnt_[1]}}		),
	.din2	({3 {dec_inst_cnt[0]}}		),
	.dout	(npc_inc_1_d		[4:2]	)
);

tlu_pct_dp_nand_macro__ports_3__width_3 npc_inc_2_d_nand   (
	.din0	(fls_npc_if_cnt_eq_2_d	[4:2]	),
