tlu_ras_ctl_msff_ctl_macro__width_6 frf_ecc_addr_w_lat  (
	.scan_in(frf_ecc_addr_w_lat_scanin),
	.scan_out(frf_ecc_addr_w_lat_scanout),
	.din	(fgu_ecc_addr_fx2	[5:0]	),
	.dout	(frf_ecc_addr_w		[5:0]	),
  .l1clk(l1clk),
