tlu_ras_ctl_msff_ctl_macro__width_14 frf_ecc_check_w_lat  (
	.scan_in(frf_ecc_check_w_lat_scanin),
	.scan_out(frf_ecc_check_w_lat_scanout),
	.din	(fgu_ecc_check_fx2	[13:0]	),
	.dout	(frf_ecc_check_w	[13:0]	),
  .l1clk(l1clk),
  .siclk(siclk),
  .soclk(soclk)
