         a_tid[2] & ~a_tid[1] &  a_tid[0],
         a_tid[2] & ~a_tid[1] & ~a_tid[0],
        ~a_tid[2] &  a_tid[1] &  a_tid[0],
        ~a_tid[2] &  a_tid[1] & ~a_tid[0],
        ~a_tid[2] & ~a_tid[1] &  a_tid[0],
        ~a_tid[2] & ~a_tid[1] & ~a_tid[0]} & 
       {8 {mrau | scac | scau}};


