assign ras_dsfar_sel_ras[7:0] =
       {| {dsfsr_7_new_in[3:0], itmu_7, dtmu_7}, 
	| {dsfsr_6_new_in[3:0], itmu_6, dtmu_6},
        | {dsfsr_5_new_in[3:0], itmu_5, dtmu_5}, 
