//  Support debug event control register function
//
// error_event_1 error_event_0	meaning
//	0		0	no event
//	0		1	precise error
//	1		0	disrupting error
//	1		1	deferred error

assign error_event_1_in[7:0] =
	write_desr[7:0] |
	write_fesr[7:0];

assign error_event_0_in[7:0] =
	precise_i_error[7:0] | precise_d_error[7:0] |
	write_fesr[7:0];

