module tlu_tel_dp (
  l2clk, 
  scan_in, 
  tcu_pce_ov, 
  spc_aclk, 
  spc_bclk, 
  tcu_scan_en, 
  trl_tel_en, 
  asi_mbist_tel_en, 
  ted_syndrome, 
  tsa_ecc, 
  ted0_cecc_err, 
  ted0_uecc_err, 
  ted0_uecc_err_, 
  ted1_cecc_err, 
  ted1_uecc_err, 
  ted1_uecc_err_, 
  trl_tsacu_en_in, 
  scan_out, 
  tel_syndrome, 
  tel_ecc, 
  tel_crit_ecc, 
  tel_tsac, 
  tel_tsau, 
  tel_tsacu_exc, 
  tel_tsac_exc, 
  tel_tsau_exc);
wire pce_ov;
wire clk;
wire stop;
wire siclk;
wire soclk;
wire se;
wire en;
wire [15:0] tsa_ecc_minbuf;
wire [3:0] trl_tsacu_en_in_minbuf;
wire ecc_lat_scanin;
wire ecc_lat_scanout;
wire tsac_in;
wire tsau_in;
wire [15:0] rd_ecc;
wire [3:0] tsacu_en;
wire tsac;
wire tsau;
wire cecc_or_;
wire [3:0] tsac_exc_;
wire [3:0] tsau_exc_;




input		l2clk;
input		scan_in;
input		tcu_pce_ov;
input		spc_aclk;
input		spc_bclk;
input		tcu_scan_en;

input		trl_tel_en;
input		asi_mbist_tel_en;

input	[15:0]	ted_syndrome;
input	[15:0]	tsa_ecc;

input		ted0_cecc_err;
input		ted0_uecc_err;
input		ted0_uecc_err_;
input		ted1_cecc_err;
input		ted1_uecc_err;
input		ted1_uecc_err_;

input	[3:0] trl_tsacu_en_in;


output		scan_out;

output	[15:0]	tel_syndrome;
output	[15:0]	tel_ecc;
output	[15:0]	tel_crit_ecc;

output		tel_tsac;
output		tel_tsau;

output	[3:0]	tel_tsacu_exc;
output	[3:0]	tel_tsac_exc;
output	[3:0]	tel_tsau_exc;



////////////////////////////////////////////////////////////////////////////////

assign pce_ov	= tcu_pce_ov;
assign clk      = l2clk;
assign stop	= 1'b0;
assign siclk	= spc_aclk;
assign soclk	= spc_bclk;
assign se       = tcu_scan_en;



////////////////////////////////////////////////////////////////////////////////
// Clock enable

tlu_tel_dp_or_macro__ports_2__width_1 en_or   (
	.din0	(trl_tel_en		),
	.din1	(asi_mbist_tel_en	),
	.dout	(en			)
);

// Data is flopped, but ECC is not,  so flop here

tlu_tel_dp_buff_macro__minbuff_1__width_20 ecc_lat_minbuff  (
	.din	({tsa_ecc		[15:0],
		  trl_tsacu_en_in	[3:0]}),
	.dout	({tsa_ecc_minbuf	[15:0],
		  trl_tsacu_en_in_minbuf[3:0]}));


tlu_tel_dp_msff_macro__width_38 ecc_lat  (
	.scan_in(ecc_lat_scanin),
	.scan_out(ecc_lat_scanout),
	.din	({tsa_ecc_minbuf	[15:0],
		  trl_tsacu_en_in_minbuf[3:0],
		  tsac_in		       ,
		  tsau_in		       ,
		  ted_syndrome		[15:0]}),
	.dout	({rd_ecc		[15:0],
		  tsacu_en		[3:0],
		  tsac			       ,
		  tsau			       ,
		  tel_syndrome		[15:0]}),
  .clk(clk),
  .en(en),
  .se(se),
  .siclk(siclk),
  .soclk(soclk),
  .pce_ov(pce_ov),
  .stop(stop)
);

assign tel_crit_ecc[15:0] =
       rd_ecc[15:0];

tlu_tel_dp_buff_macro__rep_1__width_16 ecc_buf   (
	.din	(rd_ecc			[15:0]	),
	.dout	(tel_ecc		[15:0]	)
);



tlu_tel_dp_nand_macro__ports_2__width_1 tsau_in_nand   (
	.din0	(ted0_uecc_err_			),
	.din1	(ted1_uecc_err_			),
	.dout	(tsau_in			)
);

tlu_tel_dp_nor_macro__ports_2__width_1 cecc_or_inv_nor   (
	.din0	(ted0_cecc_err			),
	.din1	(ted1_cecc_err			),
	.dout	(cecc_or_			)
);

tlu_tel_dp_nor_macro__ports_3__width_1 tsac_in_nor   (
	.din0	(cecc_or_			),
	.din1	(ted0_uecc_err			),
	.din2	(ted1_uecc_err			),
	.dout	(tsac_in			)
);

tlu_tel_dp_buff_macro__rep_1__width_1 tsac_buf   (
	.din	(tsac				),
	.dout	(tel_tsac			)
);

tlu_tel_dp_buff_macro__rep_1__width_1 tsau_buf   (
	.din	(tsau				),
	.dout	(tel_tsau			)
);


tlu_tel_dp_nand_macro__ports_2__width_4 tsac_exc_b_nand   (
	.din0	({4 {tsac}}			),
	.din1	(tsacu_en		[3:0]	),
	.dout	(tsac_exc_		[3:0]	)
);

tlu_tel_dp_nand_macro__ports_2__width_4 tsau_exc_b_nand   (
	.din0	({4 {tsau}}			),
	.din1	(tsacu_en		[3:0]	),
	.dout	(tsau_exc_		[3:0]	)
);

tlu_tel_dp_inv_macro__width_4 tsac_exc_inv  (
	.din	(tsac_exc_		[3:0]	),
	.dout	(tel_tsac_exc		[3:0]	)
);

tlu_tel_dp_inv_macro__width_4 tsau_exc_inv  (
	.din	(tsau_exc_		[3:0]	),
	.dout	(tel_tsau_exc		[3:0]	)
);

tlu_tel_dp_nand_macro__ports_2__width_4 tsacu_exc_nand   (
	.din0	(tsac_exc_		[3:0]	),
	.din1	(tsau_exc_		[3:0]	),
	.dout	(tel_tsacu_exc		[3:0]	)
);






supply0 vss; // <- port for ground
supply1 vdd; // <- port for power

// fixscan start:
assign ecc_lat_scanin            = scan_in                  ;
assign scan_out                  = ecc_lat_scanout          ;
// fixscan end:
endmodule



