       (tic_compare[4:3] == 2'b00) & (tic_compare[2]) &
       (tic_compare[1:0] == 2'b10) &
       ((~cel_tccd & ~cel_tcud) | ~tlu_ceter_de[2]);
assign tick2_compare[15:1] = 15'h0000;
