assign tick1_compare[16] =
       (tic_compare[4:3] == 2'b01) & (tic_compare[2]) &
       (tic_compare[1:0] == 2'b01) &
       ((~cel_tccd & ~cel_tcud) | ~tlu_ceter_de[1]);
// TICK_CMPR
assign tick1_compare[0] =
       (tic_compare[4:3] == 2'b00) & (tic_compare[2]) &
