       (sim0[9] & ~(| {sim0[14], sim0[12], sim0[10]})) |
       (sim0[7] & ~(| {sim0[14], sim0[12], sim0[10], sim0[8]})) |
       (sim0[5] & ~(| {sim0[14], sim0[12], sim0[10], sim0[8], sim0[6]})) |
