			sim0[4]})) |
       (sim0[1] & ~(| {sim0[14], sim0[12], sim0[10], sim0[8], sim0[6], 
			sim0[4], sim0[2]}));



assign int_level_n[3:0] =
       ({4 {real_trap[3]}} & int_level_n_3_last[3:0]) |
