		  take_htd_last,
		  take_lsr_last,
		  take_fpe_last,
		  ptake_don_last,
		  ptake_ret_last,
		  take_res_last,
		  take_ssr_last,
		  take_ssr_por_last,
		  take_icp_last,
		  take_nns_last		       }),
  .l1clk(l1clk),
  .siclk(siclk),
  .soclk(soclk)
);

assign take_don_last =
