  .l1clk(l1clk),
  .siclk(siclk),
  .soclk(soclk)
);


assign retry_in_in = 
       nns_exc | take_nns | take_ssr | take_ssr_por | 
       htd_res_icp_when_npc_nonseq;

assign retry_in =
