 	 ~ccr_cwp_asi_tid[1] &  ccr_cwp_asi_tid[0],  
	 ~ccr_cwp_asi_tid[1] & ~ccr_cwp_asi_tid[0]}};

assign trl_asireg_en =
       (| asi_wr_asireg[3:0]) | ccr_cwp_valid;



assign tlu_release_tte[3:0] = 
