       {4 {tsa_tnpc_nonseq & take_ret_last & suppress_don_ret_taken_}} & 
       trap_taken[3:0];

assign npc_nonseq_in[3:0] =
       pnpc_nonseq_in[3:0] | 
       ({4 {htd_res_icp_when_npc_nonseq_last}} & trap_taken[3:0]);

