       {4 {trap_pc_valid & take_htd_icp_last_last}} & trap_tid_dec[3:0];

assign trl_invalidate_pc[3:0] =
       pc_sel_trap_pc[3:0] | htd_icp_complete[3:0];

assign trl_invalidate_npc[3:0] = 
