tlu_tsd_dp_mux_macro__mux_aonpe__ports_3__stack_48c__width_44 trap_pstate_mux     (
	// Normal trap to hypervisor
	// IBE to 0, HPRIV to 1,  RED to 0, TCT to 0, CLE to 0, PEF to 0, 
	// AM to 0, PRIV to 0, IE to 0
	.din2 	({2'b00			       ,
		  pstate3_reg		[8   ],
		  7'b0101000		       ,	
		  pstate3_reg		[0   ],
		  2'b00			       ,
		  pstate2_reg		[8   ],
		  7'b0101000		       ,	
		  pstate2_reg		[0   ],
		  2'b00			       ,
		  pstate1_reg		[8   ],
		  7'b0101000		       ,	
		  pstate1_reg		[0   ],
		  2'b00			       ,
		  pstate0_reg		[8   ],
		  7'b0101000		       ,	
		  pstate0_reg		[0   ]}),
	// Normal trap not to hypervisor
	// HPRIV unchanged, RED to 0, TCT to 0, PEF to 1, AM to 0, PRIV to 1, 
	// IE to 0, CLE set to TLE
	.din1	({pstate3_reg		[10   ],
		  pstate3_reg		[8   ],
		  pstate3_reg		[8   ],
		  1'b0			       ,
		  pstate3_reg		[6   ],
		  5'b01010		       ,	
		  pstate3_reg		[0   ],
		  pstate2_reg		[10   ],
		  pstate2_reg		[8   ],
		  pstate2_reg		[8   ],
		  1'b0			       ,
		  pstate2_reg		[6   ],
		  5'b01010		       ,	
		  pstate2_reg		[0   ],
		  pstate1_reg		[10   ],
		  pstate1_reg		[8   ],
		  pstate1_reg		[8   ],
		  1'b0			       ,
		  pstate1_reg		[6   ],
		  5'b01010		       ,	
		  pstate1_reg		[0   ],
		  pstate0_reg		[10   ],
		  pstate0_reg		[8   ],
		  pstate0_reg		[8   ],
		  1'b0			       ,
		  pstate0_reg		[6   ],
		  5'b01010		       ,	
		  pstate0_reg		[0   ]}),
	// Any reset trap
	.din0	({11'b00001110100	       ,	
		  11'b00001110100	       ,	
		  11'b00001110100	       ,	
		  11'b00001110100	       }),
	.sel2	(trl_other_trap			),
	.sel1	(trl_stay_in_priv		),
	.sel0	(trl_reset_trap			),
	.dout	({new_pstate3		[10:0],
		  new_pstate2		[10:0],
		  new_pstate1		[10:0],
		  new_pstate0		[10:0]})
);




