module cl_dp1_mux3_12x(
in0,
in1,
in2,
sel0,
sel1,
sel2,
muxtst,
out
);

 

   input              in0;
   input              in1;
   input              in2;
   input              sel0;
   input              sel1;
   input              sel2;
   input              muxtst;
   output             out;

`ifdef LIB
`ifdef MUXOHTEST
//0in one_hot -var {sel0,sel1,sel2}
`endif

 wire [3:0] sel= {muxtst,sel2,sel1,sel0};

 assign out = (sel[2:0] == 3'b001)   ?    in0:
              (sel[2:0] == 3'b010)   ?    in1:
              (sel[2:0] == 3'b100)   ?    in2:
              (sel[3:0] == 4'b0000)  ?   1'b1:
                                         1'bx;
`endif
endmodule

