module cl_dp1_zdt64_8x(
din0,
din1,
cin,
zdt_z64_,
zdt_z32_
);

  input  [63:0]  din0;
  input  [63:0]  din1;
  input          cin;

  output         zdt_z64_;
  output         zdt_z32_;
  
  wire [63:0] p;
  wire [62:0] k;
  wire [63:0] z;
  wire zero_detect32;
  wire zero_detect64;

`ifdef LIB



assign p[63:0]       =  din0[63:0] ^  din1[63:0];
assign k[62:0]       = ~din0[62:0] & ~din1[62:0];

assign z[63:1]       =  p[63:1] ^  k[62:0];
assign z[0]          =  p[0]    ^ ~cin;

assign zero_detect32 = & z[31:0];
assign zero_detect64 = & z[63:0];

assign zdt_z32_      = ~zero_detect32;
assign zdt_z64_      = ~zero_detect64;

`endif


endmodule
module cl_dp1_ccxhdr (
l2clk,
pce0,
pce1,
pce_ov,
stop,
siclk_in,
soclk_in,
siclk_out,
soclk_out,
l1clk0,
l1clk1,
se,
si,
so,    
l1clk,                     
grant_a,
grant_x,
qsel0,
qsel0_buf,
shift,
shift_buf                         
);

input l2clk;
input pce0;
input pce1;
input pce_ov;
input stop;
input siclk_in;
input soclk_in;

output siclk_out;
output soclk_out;
output  l1clk0;
output  l1clk1;

input   l1clk;
input	se;
input   si;
input   grant_a;
input   qsel0;
input   shift;
output  so;

output  grant_x;
output  qsel0_buf;
output  shift_buf;

wire    siclk_out_unused;
wire    soclk_out_unused;

cl_dp1_ccx_l1hdr_16x hdr0 (
.l2clk(l2clk),
.se(se),
.pce(pce0),
.aclk(siclk_in),
.bclk(soclk_in),
.siclk_out(siclk_out),
.soclk_out(soclk_out),
.l1clk(l1clk0),
.pce_ov(pce_ov),
.stop(stop)
);

cl_dp1_ccx_l1hdr_16x hdr1 (
.l2clk(l2clk),
.se(se),
.pce(pce1),
.aclk(siclk_in),
.bclk(soclk_in),
.siclk_out(siclk_out_unused),
.soclk_out(soclk_out_unused),
.l1clk(l1clk1),
.pce_ov(pce_ov),
.stop(stop)
);

cl_dp1_ccx_msff_16x msff1 (
.l1clk(l1clk),
.siclk(siclk_out),
.soclk(soclk_out),
.d(grant_a),
.si(si),
.so(so),
.q(grant_x)
);

assign qsel0_buf = qsel0;
assign shift_buf = shift;

                
endmodule // cl_dp1_ccxhdr

