module n2_com_dp_32x152_cust_n2_com_array_macro__rows_32__width_152__z_array (
  rclk, 
  wclk, 
  rd_adr, 
  rd_en, 
  wr_en, 
  wr_adr, 
  din, 
  dout);

input		rclk;
input		wclk;
input	[4:0]	rd_adr;
input		rd_en;
input		wr_en;
input	[4:0]	wr_adr;
input	[152-1:0]	din;
output	[152-1:0]	dout; 



reg	[152-1:0]	mem[32-1:0];
reg	[152-1:0]	local_dout;

`ifndef NOINITMEM
// Emulate reset
integer i;
initial begin
 for (i=0; i<32; i=i+1) begin
   mem[i] = 152'b0;
 end
 local_dout = 152'b0;
end
`endif
//////////////////////
// Read/write array
//////////////////////
always @(negedge wclk) begin
   if (wr_en) begin
       mem[wr_adr] <= din;


   end
end
always @(rclk or rd_en or wr_en or rd_adr or wr_adr) begin
   if (rclk) begin
     if (rd_en) begin
         if (wr_en & (wr_adr[4:0] == rd_adr[4:0]))
             local_dout[152-1:0] <= 152'hx;
         else
             local_dout[152-1:0] <= mem[rd_adr] ;
     end
     else
             local_dout[152-1:0] <= ~(152'h0);
  end
end
assign dout[152-1:0] = local_dout[152-1:0];
supply0 vss;
supply1 vdd;




endmodule 

